curl -X POST http://localhost:8080/events \
  -H "Content-Type: application/json" \
  -d '{
    "artist": "Taylor Swift",
    "event_name": "Eras Tour",
    "reservation_opening_time": "2024-01-01T00:00:00Z",
    "reservation_closing_time": "2024-06-01T00:00:00Z", 
    "event_start_time": "2024-06-15T19:00:00Z",
    "event_end_time": "2024-06-15T23:00:00Z",
    "areas": [
      {
        "area_id": "VIP",
        "price": 500,
        "row_count": 10,
        "col_count": 20
      }
    ]
  }'

sleep 10

id=$(curl -X POST http://localhost:8080/reservations \
  -H "Content-Type: application/json" \
  -d '{
    "user_id": "user123",
    "event_id": "Eras Tour", 
    "area_id": "VIP",
    "num_of_seats": 2,
    "reservation_type": "random"
  }' | jq '.data' -r)

sleep 10

curl -X GET http://localhost:8080/reservations/$id


sleep 10




